fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let pos: i32 = t % 1800;
    let cycles: i32 = t / 1800;
    let focus: i32 = if pos < 1500 { 1 } else { 0 };
    let bg: i32 = if focus == 1 { 0x1c0808 } else { 0x08200c };
    let col: i32 = if focus == 1 { 0xe04030 } else { 0x30c050 };
    let span: i32 = if focus == 1 { 1500 } else { 300 };
    let into: i32 = if focus == 1 { pos } else { pos - 1500 };
    let rf: i32 = span - into;
    host::display::clear(bg);
    if focus == 1 {
        host::display::draw_string(24, 30, "FOCUS", col, 4);
    } else {
        host::display::draw_string(24, 30, "BREAK", col, 4);
    }
    let bw: i32 = w - 48;
    host::display::fill_rect(24, h / 2 - 20, bw, 40, 0x000000);
    host::display::fill_rect(24, h / 2 - 20, rf * bw / span, 40, col);
    let mins: i32 = (rf + 59) / 60;
    host::display::draw_number(24, h / 2 + 34, mins, 0xffffff, 3);
    host::display::draw_string(64, h / 2 + 42, "MIN LEFT", 0x808080, 1);
    host::display::draw_string(24, h - 40, "CYCLES", 0x808080, 1);
    host::display::draw_number(84, h - 44, cycles, 0xffffff, 2);
    host::display::present();
}
